import React, { useState } from "react";
import { searchMovies, getMovieDetail } from "../api/movieApi"; // 실제 경로에 맞게 수정

const SearchPage = () => {
  const [query, setQuery] = useState("");
  const [movies, setMovies] = useState([]);
  const [details, setDetails] = useState({});
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  const handleSearch = async () => {
    if (!query.trim()) return;

    setLoading(true);
    setErrorMsg("");
    setDetails({});

    try {
      const results = await searchMovies(query);
      setMovies(results);

      const detailPromises = results.map((movie) =>
        getMovieDetail(movie.movieCd).then((detail) => ({
          movieCd: movie.movieCd,
          detail,
        }))
      );

      const detailResults = await Promise.all(detailPromises);
      const detailMap = {};
      detailResults.forEach(({ movieCd, detail }) => {
        detailMap[movieCd] = detail;
      });

      setDetails(detailMap);

      if (results.length === 0) {
        setErrorMsg("검색 결과가 없습니다.");
      }
    } catch (error) {
      setErrorMsg("영화 검색 중 오류 발생");
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter") handleSearch();
  };

  return (
    <div className="p-4 max-w-3xl mx-auto">
      <h1 className="text-2xl font-bold mb-4">🎬 영화 검색 (KOFIC)</h1>

      <div className="flex gap-2 mb-4">
        <input
          type="text"
          placeholder="영화 제목을 입력하세요"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={handleKeyDown}
          className="border px-3 py-2 flex-1 rounded"
        />
        <button
          onClick={handleSearch}
          className="bg-blue-500 text-white px-4 py-2 rounded"
        >
          검색
        </button>
      </div>

      {loading && <p>🔍 검색 중...</p>}
      {errorMsg && <p className="text-red-500">{errorMsg}</p>}

      <ul className="space-y-4">
        {movies.map((movie) => {
          const detail = details[movie.movieCd] || {};

          return (
            <li
              key={movie.movieCd}
              className="border p-4 rounded shadow-sm bg-white"
            >
              <h2 className="text-lg font-bold mb-2">
                {movie.movieNm} ({movie.movieNmEn || "N/A"})
              </h2>
              <p>
                <strong>🎬 개봉일:</strong> {movie.openDt || "N/A"}
              </p>
              <p>
                <strong>🎬 감독:</strong>{" "}
                {movie.directors?.map((d) => d.peopleNm).join(", ") || "N/A"}
              </p>
              <p>
                <strong>🎭 장르 (전체):</strong> {movie.genreAlt || "N/A"}
              </p>
              <p>
                <strong>🌐 국가:</strong> {movie.repNationNm || "N/A"}
              </p>

              {/* 🔽 상세 정보 */}
              <p>
                <strong>⏱ 상영시간:</strong> {detail.showTm || "정보 없음"}
              </p>
              <p>
                <strong>👨‍🎤 배우:</strong>{" "}
                {detail.actors?.map((a) => a.peopleNm).slice(0, 5).join(", ") ||
                  "정보 없음"}
              </p>
              <p>
                <strong>🔒 관람등급:</strong>{" "}
                {detail.audits?.[0]?.watchGradeNm || "정보 없음"}
              </p>
            </li>
          );
        })}
      </ul>
    </div>
  );
};

export default SearchPage;
